'use strict';
const C=PipeCore,N=Network,K=ComponentCatalog,$=id=>document.getElementById(id),copy=o=>JSON.parse(JSON.stringify(o));
let state=copy(N.defaults),view='iso', selectedRoute=null,selectedNode=null,selectedPart=null,selectedEquipment=null;
const routeExpanded=new Set([1]),jointExpanded=new Set();
const fields=['maxVelocity','maxPressureGradient','density','viscosity','roughness','efficiency','margin','sourceZ','sourcePressure'];
const num=v=>v.trim()===''?NaN:Number(v),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),val=x=>Number.isFinite(x)?x:'';
const pipeOptions=selected=>'<option value="auto">自動選定</option>'+C.pipes.map(p=>`<option value="${p[0]}" ${selected===p[0]?'selected':''}>${p[0]}（内径${p[1]} / 外径${p[2]} mm）</option>`).join('');
function partBasisFields(r,p,j,i){const related=state.routes.filter(x=>x.id!==r.id&&(x.id===r.parent||x.parent===r.parent)),sel=(v,k)=>v===k?'selected':'';return `<label class="wide-field">K値の基準流速<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="kRefRouteId" aria-label="区間${i+1} 部品${j+1} K基準区間"><option value="" ${sel(p.kBasis||'local','local')}>この区間 P${r.parent}→P${r.id}</option>${related.map(q=>`<option value="${q.id}" ${p.kBasis==='connected'&&p.kRefRouteId===q.id?'selected':''}>接続区間 P${q.parent}→P${q.id}</option>`).join('')}</select></label>${p.type==='tee'?`<label>流れ区分<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="kFlowMode" aria-label="区間${i+1} 部品${j+1} 流れ区分">${[['unspecified','未指定'],['dividing','分流'],['combining','合流']].map(([v,label])=>`<option value="${v}" ${sel(p.kFlowMode||'unspecified',v)}>${label}</option>`).join('')}</select></label><label>継手内の流路<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="kPath" aria-label="区間${i+1} 部品${j+1} 流路">${[['unspecified','未指定'],['run','直通'],['branch','枝側']].map(([v,label])=>`<option value="${v}" ${sel(p.kPath||'unspecified',v)}>${label}</option>`).join('')}</select></label>`:''}<p class="part-note wide-field" id="k-basis-${r.id}-${j}">Kの参照速度を選んでください。</p>`}
function candidateTable(flow,s,chosen){const rows=C.pipeCandidates(flow/60,s).map(c=>`<tr><td>${c.name}${c.name===chosen?'（選定）':''}</td><td>${c.v.toFixed(3)}</td><td>${c.gradient.toFixed(1)}</td><td>${c.acceptable?'条件内':[c.overVelocity?'流速超過':'',c.overGradient?'圧損超過':''].filter(Boolean).join('・')||'計算範囲外'}</td></tr>`).join('');return `<p>直管のみ。部品損失・材料、耐圧、経済性は別途確認。</p><div class="tablewrap"><table><thead><tr><th>呼び径</th><th>流速 m/s</th><th>直管圧損 Pa/m</th><th>入力条件</th></tr></thead><tbody>${rows}</tbody></table></div>`}
function renderForm(){fields.forEach(k=>$(k).value=val(state[k]));$('valveDrawingStyle').value=state.valveDrawingStyle||'symbol';renderRoutes();update()}
function renderRoutes(){const dirs=N.dirs;$('routes').innerHTML=state.routes.map((r,i)=>{const eqs=state.equipment.filter(d=>d.node===r.id),parents=[{id:0},...state.routes.slice(0,i)];return `<details class="route-card" id="route-${r.id}" data-route-card="${r.id}" ${routeExpanded.has(r.id)?'open':''}><summary>区間 ${i+1}　P${r.parent} → P${r.id}　${dirs[r.direction]?.label||'方向未設定'} ${val(r.len)} m　${esc(r.pipe==='auto'?'自動管径':r.pipe)}</summary><div class="route-line network-route"><span class="route-number">${i+1}</span><label>接続元<select data-scope="route" data-id="${r.id}" data-key="parent" aria-label="区間${i+1} 接続元">${parents.map(p=>`<option value="${p.id}" ${r.parent===p.id?'selected':''}>P${p.id}${p.id===0?'（始点）':''}</option>`).join('')}</select></label><label>方向<select data-scope="route" data-id="${r.id}" data-key="direction" aria-label="区間${i+1} 方向">${Object.entries(dirs).map(([key,d])=>`<option value="${key}" ${r.direction===key?'selected':''}>${d.label}</option>`).join('')}</select></label><label>長さ <span>m</span><input type="number" min="0" step="any" data-scope="route" data-id="${r.id}" data-key="len" value="${val(r.len)}" ${r.direction==='diagonal'?'readonly':''} aria-label="区間${i+1} 長さ"></label><button class="del" data-action="delete-route" data-id="${r.id}">削除</button></div>${r.direction==='diagonal'?`<div class="part-grid diagonal-fields">${[['dx','東西 ΔX（東＋）'],['dy','南北 ΔY（北＋）'],['dz','上下 ΔZ（上＋）']].map(([key,label])=>`<label>${label}<span>m</span><input type="number" step="any" data-scope="route" data-id="${r.id}" data-key="${key}" value="${val(r[key])}" aria-label="区間${i+1} ${label}"></label>`).join('')}<p class="part-note" id="diagonal-info-${r.id}"></p><p class="part-note">同径45°・90°は継手を選択できます。損失は別途確認。</p></div>`:''}<p class="hint" id="sketch-issue-${r.id}"></p><div class="route-ends">P${r.parent} → P${r.id} <span id="route-summary-${r.id}"></span></div><label>区間の管径<select data-scope="route" data-id="${r.id}" data-key="pipe" aria-label="区間${i+1} 管径">${pipeOptions(r.pipe)}</select></label><details><summary>管径候補を比較</summary><div id="pipe-candidates-${r.id}" class="hint"></div></details><div class="part-list">${r.parts.map((p,j)=>{const lossOnly=['elbow','tee','reducer','combined'].includes(p.type),selectedValve=K.valves[p.catalog];return `<div class="part-card" id="part-${r.id}-${j}"><div class="part-head"><b>部品 ${j+1}</b><button class="del" data-action="delete-part" data-id="${r.id}" data-index="${j}">削除</button></div><div class="part-grid"><label>種類<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="type" aria-label="区間${i+1} 部品${j+1} 種類">${Object.entries(N.types).map(([k,v])=>`<option value="${k}" ${p.type===k?'selected':''}>${v[0]}</option>`).join('')}</select></label>${lossOnly?'<p class="part-note">損失計算用です。継手の描画は接続チェックで別途選択できます。</p>':''}${p.type==='gate'?`<label class="wide-field">部品カタログ<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="catalog" aria-label="区間${i+1} 部品${j+1} カタログ"><option value="">指定なし（仮寸法）</option>${Object.entries(K.valves).map(([key,v])=>`<option value="${key}" ${p.catalog===key?'selected':''}>${v.model} JIS10K（寸法枠）</option>`).join('')}</select></label>${selectedValve?`<details class="catalog-info wide-field"><summary>寸法・参照資料を確認</summary><p class="part-note">${selectedValve.pipe}用。面間 ${selectedValve.length}・フランジ外径 ${selectedValve.flangeDiameter} mm の寸法枠です。全開時の弁棒先端高さ H ${selectedValve.height}・ハンドル径 ${selectedValve.wheelDiameter} mm による参考枠を表示します。ハンドル実位置・実形状や干渉は示しません。フランジ厚 ${selectedValve.flangeThickness} mm・ボルト穴 ${selectedValve.holeCount}×φ${selectedValve.holeDiameter} mm・PCD ${selectedValve.pcd} mm。三面図の穴配置角度は仮定で、実物と照合してください。 <a href="https://www.kitz-valvesearch.com/valve-search/ja/detail?pid=10FCL" target="_blank" rel="noopener noreferrer">メーカー製品情報</a>（サイズ別図面・CAD取得はログインが必要）。 <a href="https://e-fsk.co.jp/wordpress/wp-content/uploads/2022/07/drawing_10fcl50-200a.pdf" target="_blank" rel="noopener noreferrer">製品寸法図の参考PDF</a>（2021年版・外部掲載、最新版を要確認）</p></details><label class="wide-field">弁棒の向き（参考枠）<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="stemDirection" aria-label="区間${i+1} 部品${j+1} 弁棒の向き"><option value="" ${!p.stemDirection?'selected':''}>自動（水平管：上／立管：北）</option>${Object.entries(N.dirs).filter(([key])=>key!=='diagonal').map(([key,d])=>`<option value="${key}" ${p.stemDirection===key?'selected':''}>${d.label}</option>`).join('')}</select></label><label class="wide-field">相手フランジとガスケット<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="mating" aria-label="区間${i+1} 部品${j+1} 相手フランジ"><option value="" ${!p.mating?'selected':''}>表示なし</option><option value="jis10k_sop_ff" ${p.mating==='jis10k_sop_ff'?'selected':''}>両側に JIS10K 鋼製 SOP-FF（参考）</option></select></label>${p.mating==='jis10k_sop_ff'?`<label>ガスケット取付時厚さ <span>mm・仮値</span><input type="number" min="0.001" step="any" data-scope="part" data-id="${r.id}" data-index="${j}" data-key="gasketThickness" aria-label="区間${i+1} 部品${j+1} ガスケット厚さ" value="${p.gasketThickness==null?3:esc(p.gasketThickness)}"></label><p class="part-note">両側に鋼製板フランジ各 ${K.matingThickness[selectedValve.pipe]} mm と入力した厚さのガスケットを配置します。3 mm は仮値です。材質、締付後厚さ、接続面、ボルト・溶接条件を確認してください。フランジ・ガスケットは概略枠で、実際の管切断長ではありません。</p>`:''}`:''}`:''}<label ${lossOnly?'style="display:none"':''}>位置 <span>区間の %</span><input type="number" min="0" max="100" step="any" data-scope="part" data-id="${r.id}" data-index="${j}" data-key="position" value="${val(p.position)}" aria-label="区間${i+1} 部品${j+1} 位置"></label><label>損失係数 K<input type="number" min="0" step="any" data-scope="part" data-id="${r.id}" data-index="${j}" data-key="k" value="${val(p.k)}" aria-label="区間${i+1} 部品${j+1} K"></label>${partBasisFields(r,p,j,i)}<label class="wide-field">K値の根拠 <span>資料・型式など</span><input type="text" maxlength="150" data-scope="part" data-id="${r.id}" data-index="${j}" data-key="kRef" value="${esc(typeof p.kRef==='string'?p.kRef:'')}" aria-label="区間${i+1} 部品${j+1} K値の根拠"></label><div class="wide-field"><button class="add-part" type="button" data-action="confirm-k" data-id="${r.id}" data-index="${j}">この条件でK値を確認</button><p class="part-note" id="k-status-${r.id}-${j}">要確認</p></div>${lossOnly?`<label class="wide-field">関連する接続点<select data-scope="part" data-id="${r.id}" data-index="${j}" data-key="jointId" aria-label="区間${i+1} 部品${j+1} 接続点"><option value="">未関連付け</option><option value="${r.parent}" ${p.jointId===r.parent?'selected':''}>P${r.parent}（区間始点）</option></select></label>`:''}<label>個数 <span>${lossOnly?'':'図形は1個ずつ'}</span><input type="number" min="1" step="1" data-scope="part" data-id="${r.id}" data-index="${j}" data-key="count" value="${val(p.count)}" aria-label="区間${i+1} 部品${j+1} 個数"></label><label ${lossOnly?'style="display:none"':''}>${selectedValve?'弁の面間':'外形の長さ'} <span>mm</span><input type="number" min="0" step="any" data-scope="part" data-id="${r.id}" data-index="${j}" data-key="bodyLength" value="${selectedValve?selectedValve.length:(p.bodyLength==null?'':esc(p.bodyLength))}" ${selectedValve?'disabled':''} placeholder="自動の仮値" aria-label="区間${i+1} 部品${j+1} 外形の長さ"></label><label ${lossOnly?'style="display:none"':''}>外形の幅 <span>mm</span><input type="number" min="0" step="any" data-scope="part" data-id="${r.id}" data-index="${j}" data-key="bodyWidth" value="${selectedValve?selectedValve.flangeDiameter:(p.bodyWidth==null?'':esc(p.bodyWidth))}" ${selectedValve?'disabled':''} placeholder="自動の仮値" aria-label="区間${i+1} 部品${j+1} 外形の幅"></label></div></div>`}).join('')}<button class="add-part" data-action="add-part" data-id="${r.id}">＋ この区間に部品を追加</button></div><div class="equipment-list">${eqs.map(d=>`<div class="equipment-card"><div class="part-head"><b>接続設備 EQ${d.id}</b><button class="del" data-action="delete-equipment" data-id="${d.id}">削除</button></div><div class="part-grid"><label>設備名<input type="text" maxlength="50" data-scope="equipment" data-id="${d.id}" data-key="name" value="${esc(d.name)}" aria-label="設備${d.id} 名前"></label><label>必要流量 <span>m³/min</span><input type="number" min="0" step="any" data-scope="equipment" data-id="${d.id}" data-key="flow" value="${val(d.flow)}" aria-label="設備${d.id} 必要流量"></label><label>必要圧力 <span>kPa・ゲージ圧</span><input type="number" step="any" data-scope="equipment" data-id="${d.id}" data-key="pressure" value="${val(d.pressure)}" aria-label="設備${d.id} 必要圧力"></label></div></div>`).join('')}<div class="route-actions"><button class="add-part" data-action="add-equipment" data-id="${r.id}">＋ P${r.id} に設備を接続</button><button class="add-part" data-action="add-route" data-id="${r.id}">＋ P${r.id} から区間を追加</button></div></div></details>`}).join('');renderRouteIndex()}
function update(){refreshDiagonalInfo();const r=N.calculate(state);$('status').textContent=r.errors.length?'入力を確認':'計算済み';$('error').hidden=!r.errors.length;$('error').textContent=r.errors.join(' ');if(r.errors.length){$('jointStatus').textContent='計算条件を確認';$('jointChecks').innerHTML='<p class="hint">接続チェックには有効な経路と各設備の入力が必要です。</p>';$('assessmentSummary').textContent='計算条件が不完全のため、接続と損失の登録状況は未評価です。';$('results').innerHTML='';renderIncompleteSketch();$('drawingError').hidden=true;$('drawingWarnings').innerHTML='';$('report').disabled=true;$('isoDxf').disabled=$('viewsDxf').disabled=$('drawingPdf').disabled=true;document.querySelectorAll('[id^="route-summary-"],[id^="pipe-candidates-"]').forEach(e=>e.textContent='');afterUpdate(r);return}$('report').disabled=false;const review=N.inspectConnections(state,r);renderJointReview(review,r);$('status').textContent=review.missing||review.unreferenced.length?'概算・要確認':'概算';$('assessmentSummary').textContent=`接続 ${review.missing} 件が要確認。K値の根拠が未入力・条件変更後に未確認の部品 ${review.unreferenced.length} 件。その他の未評価項目も残ります。`;const fmt=(n,d=2)=>Number(n).toFixed(d),flowFmt=n=>Math.abs(n)<0.0001?Number(n).toExponential(3):Number(n.toPrecision(6)).toString(),metric=(t,v,u)=>`<div class="metric"><div class="caption">${t}</div><strong>${v} <small>${u}</small></strong></div>`;let equipment=r.equipment.map(e=>`<tr><td>${esc(e.name)}${e.id===r.critical.id?' <span class="critical">基準</span>':''}</td><td>${flowFmt(e.flow)}</td><td>${fmt(e.loss)}</td><td>${fmt(e.staticHead)}</td><td>${fmt(e.pressureHead)}</td><td>${fmt(e.total)}</td><td>${fmt(e.excessHead)}</td></tr>`).join(''),edges=state.routes.map((route,i)=>{let e=r.edges.get(route.id);return `<tr><td>${i+1}（P${route.parent}→P${route.id}）</td><td>${flowFmt(e.flow)}</td><td>${e.name}</td><td>${fmt(e.v)}</td><td>${fmt(e.gradient,1)}</td><td>${fmt(e.loss)}</td></tr>`}).join('');$('results').innerHTML=`<div class="metrics">${metric('ポンプ流量',flowFmt(r.totalFlow),'m³/min')}${metric('設計揚程',fmt(r.design),'m')}${metric('必要軸動力',fmt(r.power,3),'kW')}${metric('基準となる設備',esc(r.critical.name),'')}</div><p class="hint results-note">設備別必要揚程は余裕率を含まず、経路損失は共通配管を含みます。揚程差は基準設備との差で、実流量の自動調整は含みません。</p><div class="tablewrap"><table class="result-table"><thead><tr><th>設備</th><th>流量<br>m³/min</th><th>経路損失<br>m</th><th>高さ差<br>m</th><th>圧力差水頭<br>m</th><th>必要揚程<br>m</th><th>揚程差<br>m</th></tr></thead><tbody>${equipment}</tbody></table></div><h3>区間別の計算</h3><div class="tablewrap"><table class="result-table"><thead><tr><th>区間</th><th>流量<br>m³/min</th><th>管径</th><th>流速<br>m/s</th><th>直管圧損<br>Pa/m</th><th>損失<br>m</th></tr></thead><tbody>${edges}</tbody></table></div>${[...r.edges.values()].some(e=>e.overVelocity)?'<p class="warning">手動で指定した管径に、許容流速を超える区間があります。</p>':''}${r.negativeHead?'<p class="warning">最大の必要揚程が0以下です。運転点の成立を別途検討してください。</p>':''}<p class="warning">入力した流量は設計上の想定値です。並列経路の必要揚程が異なる場合、調整弁などで流量を確保する検討が必要です。</p>`;state.routes.forEach(route=>{let edge=r.edges.get(route.id),el=$('route-summary-'+route.id);if(el)el.textContent=`　${flowFmt(edge.flow)} m³/min ・ ${edge.name} ・ 外径 ${edge.outerDiameter} mm ・ 直管圧損 ${fmt(edge.gradient,1)} Pa/m`;const list=$('pipe-candidates-'+route.id);if(list)list.innerHTML=candidateTable(edge.flow,state,edge.name)});document.querySelectorAll('[data-scope="part"][data-key="bodyLength"],[data-scope="part"][data-key="bodyWidth"]').forEach(el=>{const route=state.routes.find(x=>x.id===+el.dataset.id),size=C.partSize(route.parts[+el.dataset.index],r.edges.get(route.id).outerDiameter);el.placeholder='仮値 '+(el.dataset.key==='bodyLength'?size.length:size.width)});state.routes.forEach(route=>route.parts.forEach((part,i)=>{const el=$(`k-status-${route.id}-${i}`);if(!el)return;const status=N.lossStatus(state,r,route,part),basis=$(`k-basis-${route.id}-${i}`);if(basis)basis.textContent=N.partBasisSummary(state,r,route,i);el.textContent=status==='current'?`条件一致。K値の適用性は設計者が確認してください。`:status==='stale'?'根拠または計算条件が変更されています。K値を見直し、この条件で確認してください。':'K値の根拠を入力し、この条件で確認してください。'}));const warnings=N.drawingWarnings(state,r);$('drawingWarnings').innerHTML=warnings.length?`<p class="warning">DXFには検討用の警告 ${warnings.length} 件を出力します。</p><ul>${warnings.map(w=>`<li>${esc(w.text)}</li>`).join('')}</ul>`:'<p class="hint">接続・損失の入力に関する警告はありません。図面は引き続き概略図です。</p>';const errors=N.drawingErrors(state,r);$('drawingError').hidden=!errors.length;$('drawingError').textContent=errors.join(' ');$('isoDxf').disabled=$('viewsDxf').disabled=$('drawingPdf').disabled=!!errors.length;if(errors.length){renderIncompleteSketch()}else renderPreview(r);afterUpdate(r,review)}
const jointKinds={elbow:'エルボ',reducer:'異径継手',reducing_elbow:'異径エルボまたは組合せ',tee:'チーズ形分岐'};
